const payload = $input.first().json;
const body = payload.body || payload;
const headers = payload.headers || {};
const expected = $env.WEBHOOK_TOKEN;
if (expected && headers['x-webhook-token'] !== expected) { throw new Error('Token webhook invalide'); }

const { brand, category, flavor, theme, description, artDirection, images } = body;
if (!brand || !category || !theme) { throw new Error('Champs requis manquants (brand, category, theme)'); }
if (!images || !images.length) { throw new Error('Aucune image fournie'); }

// Défense en profondeur : le backend nettoie déjà, mais le node peut être appelé
// directement. Retire caractères de contrôle, collapse les espaces, tronque.
const clean = (s, max) => String(s || '').replace(/\p{Cc}/gu, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const desc = clean(description, 120);
const art = clean(artDirection, 200);

const NL = String.fromCharCode(10);
const DA_SYSTEM = "You are an art director for commercial product photography. Given a product, you design ONE specific scene that makes the product's identity legible at a glance.\n\nMethod:\n1. Identify what the product is literally made of, where it comes from, and when it is consumed.\n2. Derive an environment from that identity — not a generic studio, not a stock background. Crisps come from potatoes and farms. San Pellegrino comes from an Italian table. Energy drinks belong where energy is spent. A frozen croissant belongs in a morning kitchen.\n3. Choose a surface the product physically rests on, and at most four props that belong in that world. Every prop must have a reason to be there.\n4. Respect the requested theme as a STYLE constraint applied to that environment, not as a replacement for it. \"Luxe\" on crisps is a refined farmhouse, not a marble podium.\n\nRules:\n- Be concrete. \"Rustic wooden crate on straw, raw potatoes with soil still on them\" beats \"farm setting\".\n- Never describe the product's own packaging, label, logo or text. Another system handles that.\n- Never include people, hands, faces, other brands, or any text, sign or signage in the scene.\n- Keep each field under 25 words.\n\nInput: brand, category, description, flavour, theme.\nOutput: the JSON object only.";
const DA_SCHEMA = {"type":"object","required":["setting","surface","props","framing","light","palette","mood"],"properties":{"setting":{"type":"string"},"surface":{"type":"string"},"props":{"type":"array","items":{"type":"string"},"maxItems":4},"framing":{"type":"string"},"light":{"type":"string"},"palette":{"type":"string"},"mood":{"type":"string"}}};
const DA_FEWSHOT = [{"role":"user","text":"brand: Lay's\ncategory: crisps\ndescription: (none)\nflavour: (none)\ntheme: classique"},{"role":"model","text":"{\"setting\":\"old stone barn interior, afternoon light through an open door\",\"surface\":\"rough wooden crate lined with burlap\",\"props\":[\"raw potatoes with soil\",\"scattered straw\",\"vintage metal scale\"],\"framing\":\"eye-level, product centred on the crate\",\"light\":\"warm directional daylight from the left, dust in the air\",\"palette\":\"earthy browns, straw gold, muted green\",\"mood\":\"rustic, authentic, artisanal\"}"},{"role":"user","text":"brand: San Pellegrino\ncategory: sparkling water\ndescription: (none)\nflavour: lemon\ntheme: ete"},{"role":"model","text":"{\"setting\":\"sunlit terrace overlooking an Italian coastal village\",\"surface\":\"marble bistro table\",\"props\":[\"fresh lemons with leaves\",\"linen napkin\",\"small espresso cup\"],\"framing\":\"slightly low angle, bottle standing\",\"light\":\"midday Mediterranean sun, hard shadows, bright bounce\",\"palette\":\"azure blue, lemon yellow, warm white\",\"mood\":\"bright, leisurely, Mediterranean\"}"},{"role":"user","text":"brand: Nutella\ncategory: frozen pastry\ndescription: croissant filled with Nutella\nflavour: (none)\ntheme: classique"},{"role":"model","text":"{\"setting\":\"morning kitchen counter, soft window light\",\"surface\":\"white ceramic plate on light oak\",\"props\":[\"open Nutella jar\",\"hazelnuts\",\"coffee cup\",\"linen cloth\"],\"framing\":\"eye-level, three-quarter view\",\"light\":\"soft diffused morning light from the right\",\"palette\":\"warm cream, hazelnut brown, soft white\",\"mood\":\"cosy, homely, inviting\"}"}];

const daContents = DA_FEWSHOT.map((ex) => ({ role: ex.role, parts: [{ text: ex.text }] }));
const userLine = ['brand: ' + brand, 'category: ' + category, 'description: ' + (desc || '(none)'), 'flavour: ' + (flavor || '(none)'), 'theme: ' + theme].join(NL);
daContents.push({ role: 'user', parts: [{ text: userLine }] });

const daBody = {
  systemInstruction: { parts: [{ text: DA_SYSTEM }] },
  contents: daContents,
  generationConfig: { responseMimeType: 'application/json', responseSchema: DA_SCHEMA, temperature: 0.9 }
};

return [{ json: { daBody, body, desc, art } }];

const da = $input.first().json;                       // réponse Directeur Artistique (ou erreur si continueOnFail)
const ctx = $('Build DA Request').first().json;       // body original + champs nettoyés
const { body, desc, art } = ctx;
const { brand, category, flavor, theme, images } = body;
const NL = String.fromCharCode(10);

const lead = 'Professional advertising photograph of ' + brand + ' ' + category + (desc ? ' \u2014 ' + desc : '') + (flavor ? ', ' + flavor + ' flavor' : '') + '.';
const FIDELITY = "Keep the exact product packaging, label, logo and typography from the reference image unchanged and photorealistic.";
const AVOID = "AVOID: altered or invented packaging text, distorted logo, extra products, hands, faces, watermarks, added slogans, cartoon or illustration style, visible AI artefacts.";
const PRESETS = {
  "classique": "Iconic minimalist studio advertisement: the product stands centered on a glossy reflective surface in front of a smooth gradient backdrop in the brand's signature colors, crisp softbox studio lighting with a subtle rim light, clean high-end commercial poster look, sharp product focus, neutral elegant composition.",
  "ete": "Bright outdoor summer beach scene: the product sits on golden sand next to splashing turquoise water and scattered ice cubes, palm-leaf shadows, clear blue sky, strong warm sunlight, vivid saturated summer colors, fresh condensation droplets, relaxed vacation lifestyle mood, shallow depth of field.",
  "extravagant": "Maximalist surreal advertisement: the product levitates at the center of an explosive energy burst with splashing liquid crowns, crackling electric arcs, shattered flying ice and swirling neon-colored smoke and sparks, dramatic chiaroscuro spotlight, bold clashing complementary colors, dynamic diagonal composition, frozen high-speed motion, luxurious futuristic set, hyper-detailed.",
  "sport": "High-energy sports action scene: the product on the rough concrete of an urban court or stadium track at golden hour, shot from a dynamic low camera angle, motion-blurred athletes and flying water and dust in the background, dramatic hard rim lighting, punchy high-contrast colors, intense adrenaline mood.",
  "fete": "Vibrant nightclub party scene: the product on a glossy bar counter surrounded by glowing purple and blue neon lights and laser beams, a blurred dancing crowd as colorful bokeh, dark atmosphere with vivid colored reflections on a wet surface, cinematic night color grade, energetic festive mood.",
  "luxe": "Ultra-premium luxury scene: the product on a polished dark marble pedestal with soft golden accent lighting and elegant deep shadows, minimalist sophisticated set, a wisp of subtle smoke, moody overhead spotlight, sleek exclusive editorial aesthetic, refined black-and-gold palette.",
  "noel": "Cozy Christmas winter scene: the product on a rustic wooden table surrounded by soft snow, pine branches, red baubles and warm glowing fairy-light bokeh, a soft fireplace glow in the background, warm golden festive color palette, magical holiday mood."
};

// Extrait et valide le JSON du Directeur Artistique. Un JSON syntaxiquement
// valide mais amputé d'un champ déclenche aussi le repli.
function parseDA(resp) {
  try {
    const cands = (resp && resp.candidates) || (resp && resp.body && resp.body.candidates) || [];
    const parts = cands[0] && cands[0].content && cands[0].content.parts;
    const text = parts && parts[0] && parts[0].text;
    if (!text) return null;
    const o = JSON.parse(text);
    const req = ['setting', 'surface', 'props', 'framing', 'light', 'palette', 'mood'];
    for (const k of req) { if (o[k] == null || o[k] === '') return null; }
    if (!Array.isArray(o.props)) return null;
    return o;
  } catch (e) { return null; }
}

// Transforme les 7 champs en bloc SCÈNE (jamais le packaging).
function renderScene(o) {
  const props = o.props.slice(0, 4).join(', ');
  return [
    'SCENE: ' + o.setting + '. The product rests on ' + o.surface + '.' + (props ? ' Nearby: ' + props + '.' : ''),
    'FRAMING: ' + o.framing,
    'LIGHT: ' + o.light,
    'PALETTE: ' + o.palette,
    'MOOD: ' + o.mood
  ].join(NL);
}

// Priorité : décor manuel > scène IA valide > repli thème statique.
let scene, source;
if (art) {
  scene = art; source = 'manual';
} else {
  const parsed = parseDA(da);
  if (parsed) { scene = renderScene(parsed); source = 'auto'; }
  else { scene = PRESETS[theme] || PRESETS.classique; source = 'fallback'; }
}

const prompt = lead + ' ' + scene + ' ' + FIDELITY + ' ' + AVOID;

const parts = [{ text: prompt }];
for (const img of images) { parts.push({ inline_data: { mime_type: img.mimeType || 'image/jpeg', data: img.data } }); }

const geminiBody = {
  contents: [{ role: 'user', parts }],
  generationConfig: { responseModalities: ['TEXT', 'IMAGE'], imageConfig: { aspectRatio: '4:5' } }
};
return [{ json: { geminiBody, prompt, artDirectionSource: source } }];

const resp = $input.first().json;
const candidates = resp.candidates || (resp.body && resp.body.candidates) || [];
let image = null;
let mimeType = 'image/png';
for (const c of candidates) {
  const parts = (c.content && c.content.parts) || [];
  for (const p of parts) {
    const inline = p.inlineData || p.inline_data;
    if (inline && inline.data) { image = inline.data; mimeType = inline.mimeType || inline.mime_type || mimeType; break; }
  }
  if (image) break;
}
if (!image) { throw new Error('Vertex/Gemini: aucune image renvoyee. ' + JSON.stringify(resp).slice(0, 800)); }
const bp = $('Build Prompt').first().json;
return [{ json: { image, mimeType, prompt: bp.prompt, artDirectionSource: bp.artDirectionSource } }];
